# start the slow build as a Sandbox process and wait for it here
node --input-type=module <<'JS'
const { LayerFS } = await import(process.env.DSH_LAYERFS_SDK);
const { LayerFSBackend } = await import(process.env.DSH_LAYERFS_BACKEND);
const lf = await LayerFS.open(process.env.DSH_LAYERFS_PROJECT);
const be = LayerFSBackend.of(lf);
try {
  const { items } = await lf.sandbox.list_workspaces("{{sandbox}}");
  const siteAt = items.find((w) => w.branch === "site");
  const site = { sandbox: siteAt.sandbox, path: siteAt.path };
  const build = await be.daemon.process.start(site, "sh build.sh --slow");
  console.log(`start sh build.sh --slow → ${build.kind} (${build.process})`);
  let status = "running";
  while (status === "running") {
    await new Promise((resolve) => setTimeout(resolve, 2000));
    status = (await be.daemon.process.list()).items.find((p) => p.id === build.process)?.status ?? "gone";
  }
  console.log(`build ${status}`);
  const out = await lf.workspace.exec(site, "cat .next/BUILD_ID && ls .next/server/app");
  console.log(`${out.stdout}${out.stderr}`);
} finally {
  await lf.close();
}
